    contentHtml: `<!-- target keyword: 사주팔자 기초 | secondary: 사주팔자 뜻, 사주 원리 -->
<p>사주팔자 기초를 한 문장으로 요약하면, 태어난 연·월·일·시로 네 개의 기둥(四柱)을 세우고 각 기둥의 천간·지지를 합친 여덟 글자(八字)로 기질과 시간의 흐름을 읽는 체계입니다. 이 글은 처음 배우는 분을 위해 구조부터 해석 순서까지 원리만 정리합니다.</p>
<h2>사주팔자란: 여덟 글자에 담긴 정보 지도</h2>
<p>사주팔자(四柱八字)는 운세 번호가 아니라 복합 정보 지도입니다. 여덟 글자 안에는 오행(목화토금수)의 배분, 음양의 균형, 그리고 십성이라는 역할 분류가 모두 담겨 있습니다. 명리학이 이것을 공부하는 이유는 운명을 단정하기 위해서가 아니라, 반복되는 행동·관계·시간 패턴을 이해해 의사결정의 질을 높이기 위해서입니다. 수천 년간 동아시아에서 자기 이해의 도구로 다듬어져 온 체계이지만, 의료·법률·재무 결정은 반드시 전문가와 상담해야 합니다.</p>
<h2>네 기둥의 역할: 연주·월주·일주·시주</h2>
<ul>
<li>연주(年柱) — 태어난 해. 조상·사회적 배경·초년 환경의 참고점</li>
<li>월주(月柱) — 태어난 달. 부모·형제·청년기의 토대이자 가장 강한 계절 정보. 일간의 강약 판단에 결정적</li>
<li>일주(日柱) — 태어난 날. 천간의 일간(日干)이 "나 자신"이라는 모든 해석의 기준점</li>
<li>시주(時柱) — 태어난 시간. 자녀·말년·하루의 에너지 리듬</li>
</ul>
<p>초보자가 가장 흔히 하는 실수는 연주의 띠 하나, 혹은 특정 글자 하나로 전체를 판단하는 것입니다. 해석 정확도는 네 기둥의 상호작용(합·충·형 등)과 현재 대운·세운을 함께 볼 때 올라갑니다.</p>
<h2>재료 이해: 천간 10개, 지지 12개</h2>
<p>천간은 갑·을·병·정·무·기·경·신·임·계 10개, 지지는 자·축·인·묘·진·사·오·미·신·유·술·해 12개입니다. 천간과 지지가 결합해 60개의 조합(육십갑자)이 만들어지고, 이것이 연·월·일·시에 순환 배치됩니다. 각 글자는 오행과 음양 속성을 가지며, 지지는 내부에 지장간이라는 복수의 천간을 품고 있어 겉 글자보다 복합적입니다. 글자별 성질이 궁금하다면 이 파일의 <a href="/insights/cheongan-jiji-complete-explanation/">천간 지지 완벽 해설</a>에서 하나씩 확인할 수 있습니다.</p>
<h2>오행의 상생·상극: 사주를 움직이는 문법</h2>
<p>오행은 목→화→토→금→수→목 순서로 서로를 생(生)하고, 목→토→수→화→금→목 순서로 서로를 극(剋)합니다. 상생과 상극은 좋고 나쁨의 잣대가 아니라 역학 구조를 읽는 분석 도구입니다. 예를 들어 목(木) 일간에게 금(金)이 많으면 기준과 압박을 강하게 받는 구조이므로, 이를 조절할 오행이 무엇인지 찾는 방식으로 해석이 진행됩니다. 오행별 성질은 <a href="/insights/five-elements-ohang-complete-guide/">오행 완전 정리</a>에서 자세히 다룹니다.</p>
<h2>초보자 5단계 해석 순서</h2>
<ul>
<li>1단계 — 일간 확인: 나를 나타내는 글자의 오행과 음양 파악</li>
<li>2단계 — 월지 계절: 태어난 계절이 일간을 돕는지 극하는지로 신강·신약의 방향 가늠</li>
<li>3단계 — 오행 분포: 여덟 글자에서 과잉 오행과 빠진 오행 확인</li>
<li>4단계 — 십성 구조: 비겁·식상·재성·관성·인성 중 강약 파악</li>
<li>5단계 — 대운·세운: 현재 흐름이 원국과 어떻게 상호작용하는지 확인</li>
</ul>
<h2>바르게 활용하는 자세</h2>
<p>같은 사주를 가진 사람도 환경과 선택에 따라 전혀 다른 삶을 삽니다. 바른 질문은 "내 사주가 이렇다더라"가 아니라 "이 구조에서 어떤 보완 전략을 취할 수 있는가"입니다. 재성이 강하면 자원 관리 체계를 만들고, 관성이 약하면 자기 규율 루틴을 의지적으로 설계하는 식입니다.</p>
<p>이론을 잡았다면 <a href="/manse/">무료 만세력</a>에서 내 여덟 글자를 직접 확인하고, 조금 더 깊은 구조 해석은 심화 가이드인 <a href="/insights/saju-four-pillars-basics/">사주팔자 구조 심화 가이드</a>로 이어가 보세요.</p>`,
