        body: `사주팔자(四柱八字)는 태어난 연도·월·일·시를 각각 하나의 기둥으로 세워 총 네 개의 기둥(四柱)을 만들고, 각 기둥의 천간(天干)과 지지(地支)를 합쳐 여덟 글자(八字)를 구성하는 동양 명리학의 핵심 체계입니다. 예를 들어 1990년 5월 15일 낮 12시에 태어난 사람은 경오년·기사월·을해일·병오시라는 네 개의 기둥과 여덟 글자를 가지게 됩니다. 이 여덟 글자는 단순한 운세 번호가 아니라 오행(목·화·토·금·수)의 배분, 음양의 균형, 십성(비겁·식상·재성·관성·인성)이라는 역할 분류가 모두 담겨 있는 복합적인 정보 지도입니다. 명리학에서 사주팔자를 공부하는 이유는 운명을 단정하기 위해서가 아니라, 반복되는 행동·관계·시간 패턴을 이해해 의사결정의 질을 높이는 데 있습니다. 과학적 검증 수준에 대해서는 다양한 견해가 존재하지만, 수천 년간 동아시아 문화권에서 자기 이해와 삶의 지혜로 활용되어 온 체계라는 점은 부인할 수 없습니다. 본 콘텐츠는 오락 및 자기 성찰 목적으로 활용하시길 권장하며, 실제 의료·법률·금융 결정은 반드시 전문가와 상담하시기 바랍니다.`,
