        body: `사주의 네 기둥은 각각 다른 시간축을 대표하며, 삶의 영역과 대략적으로 연결됩니다. 연주(年柱)는 태어난 해를 나타내며 조상·사회적 배경·초년의 환경을 읽는 참고점이 됩니다. 월주(月柱)는 태어난 달로 부모·형제·청년기의 기질적 토대를 보여주며, 사주에서 가장 강한 계절성 정보를 담고 있어 일간(日干)의 강약을 판단하는 데 결정적 역할을 합니다. 일주(日柱)는 태어난 날로, 천간의 일간(日干)은 '나 자신'이라는 기준점이 됩니다. 명리학에서는 모든 해석이 일간을 기준으로 이루어집니다. 시주(時柱)는 태어난 시간으로 자녀·말년·하루의 에너지 리듬과 관련지어 해석합니다. 초보자가 흔히 하는 실수는 연주만 보거나 특정 기둥의 한 글자만으로 전체를 판단하는 것입니다. 사주 해석 정확도는 네 기둥 전체의 상호작용, 즉 합(合)·충(衝)·형(刑)·파(破)·해(害) 관계와 대운∙세운의 현재 흐름을 함께 볼 때 크게 높아집니다.`,
