        body: `0번 바보(The Fool)는 새로운 시작, 순수한 가능성, 두려움 없는 도전을 의미합니다. 역방향은 무계획·충동·집중력 분산을 나타냅니다. 1번 마법사(The Magician)는 의지, 기술, 자원 활용 능력의 카드로, 내가 이미 가진 도구들을 잘 쓰라는 메시지입니다. 역방향은 능력 미활용·사기·자기 의심을 나타냅니다. 2번 여사제(The High Priestess)는 직관, 잠재적 지식, 기다림의 지혜입니다. 역방향은 정보 억압·직관 무시를 나타냅니다. 3번 여황제(The Empress)는 풍요, 창조, 돌봄의 에너지로 성장 환경 조성에 관한 메시지를 줍니다. 4번 황제(The Emperor)는 구조, 안정, 리더십, 경계 설정입니다. 역방향은 권위주의·통제 욕구를 나타냅니다. 5번 교황(The Hierophant)은 전통, 학습 체계, 제도적 지식의 가치를 강조합니다. 6번 연인(The Lovers)은 가치 선택, 관계의 합의, 내면의 통합입니다. 7번 전차(The Chariot)는 목표 추진력, 내면 통제, 방향 고수의 에너지로 결승선을 향해 흔들리지 말라는 메시지입니다.`,
