    contentHtml: `<!-- target keyword: 자미두수 | secondary: 자미두수 명반, 12궁, 14주성 -->
<p>자미두수(紫微斗數)는 생년월일시로 12개의 궁(宮)으로 나뉜 명반(命盤)을 만들고, 자미성을 비롯한 별들을 배치해 인생을 영역별로 읽는 동양 점성학입니다. 사주가 오행의 큰 흐름을 본다면, 자미두수는 직업·배우자·재물 같은 구체 영역을 궁 단위로 봅니다. 이 글은 명반을 처음 여는 분을 위한 입문 지도입니다.</p>
<h2>자미두수란: 임금별로 헤아리는 운명 지도</h2>
<p>자미(紫微)는 북두칠성의 중심에 있다고 여겨진 임금별 자미성을 뜻하고, 두수(斗數)는 별자리를 헤아린다는 뜻입니다. 송나라 시기에 체계화된 것으로 전해지며, 중국·대만·홍콩에서는 명리학만큼 널리 쓰입니다. 한국에서는 상대적으로 덜 알려졌지만 명리학 이후의 심화 공부로 관심이 빠르게 늘고 있습니다.</p>
<h2>명반의 뼈대: 12궁 구조</h2>
<p>명반은 12개의 궁으로 구성됩니다. 명궁(나 자신·기질), 형제궁, 부처궁(배우자·이성 관계), 자녀궁, 재백궁(재물), 질액궁(건강), 천이궁(이동·외부 활동), 노복궁(친구·조력자), 관록궁(직업), 전택궁(부동산·주거), 복덕궁(정신적 만족), 부모궁입니다. 같은 별이라도 어느 궁에 앉느냐에 따라 발현되는 영역이 완전히 달라진다는 것이 자미두수의 기본 문법입니다.</p>
<h2>14주성: 명반의 주연 배우들</h2>
<p>자미두수의 별 가운데 해석의 중심이 되는 것이 14주성(主星)입니다. 자미(리더십·존귀), 천기(지략·기획), 태양(활동성·사회적 영향력), 무곡(재무·실행), 천동(온화·복덕), 염정(권위와 욕망의 양면), 천부(안정·재고), 태음(감수성·직관), 탐랑(욕망·매력·다재다능), 거문(언변·구설), 천상(보좌·균형), 천량(원칙·보호), 칠살(결단·개척), 파군(파괴 후 재건)입니다. 명궁에 어떤 주성이 앉았는지가 기질 해석의 출발점이고, 주성이 없는 궁은 마주 보는 궁(대궁)의 별을 빌려 읽습니다.</p>
<h2>사화(四化): 해에 따라 별에 불이 들어온다</h2>
<p>자미두수를 역동적으로 만드는 장치가 사화입니다. 태어난 해(그리고 유년의 해)의 천간에 따라 특정 별에 화록(祿)·화권(權)·화과(科)·화기(忌)가 붙습니다. 화록은 재물과 순조로움, 화권은 권한과 주도권, 화과는 명예와 시험·문서운, 화기는 막힘과 집착·아쉬움의 신호입니다. 같은 명반이라도 어떤 별이 화기를 맞았는지에 따라 그 궁의 과제가 선명해지므로, 입문 단계에서도 사화의 위치는 꼭 확인할 가치가 있습니다.</p>
<h2>사주 명리학과의 차이</h2>
<p>두 체계 모두 생년월일시를 쓰지만 언어가 다릅니다. 명리학은 천간·지지의 오행 관계와 십성으로 "이 시기에 어떤 에너지가 들어오는가"라는 큰 흐름을 읽는 데 강하고, 자미두수는 12궁과 별의 조합으로 "어느 영역에서 어떤 특성이 나타나는가"를 입체적으로 보는 데 강합니다. 어느 쪽이 더 정확하냐보다, 질문에 맞는 도구를 고르고 보완적으로 쓰는 것이 실용적입니다.</p>
<h2>명반 보는 법: 입문 3단계</h2>
<ul>
<li>1단계 — 명궁 확인: 내 명궁의 위치와 그 안의 주성을 파악합니다. 모든 해석의 기준점입니다</li>
<li>2단계 — 삼방사정 연결: 명궁과 삼합을 이루는 재백궁·관록궁(그리고 대궁인 천이궁)을 함께 보면 나·돈·일의 연결 고리가 보입니다</li>
<li>3단계 — 사화 위치 확인: 화록·화권·화과·화기가 어느 궁에 들어갔는지 보고 올해의 순풍과 과제를 잡습니다</li>
</ul>
<p>이 3단계만으로도 기질과 커리어 방향의 큰 그림이 잡힙니다. <a href="/ziwei/">무료 자미두수 명반</a>에서 생년월일시 입력만으로 내 명반을 바로 열 수 있고, 별들의 조합 해석까지 원한다면 <a href="/ziwei-ai/">자미두수 전문가 상담</a>이 이어서 풀어 줍니다. 14주성 각각의 성격을 더 깊이 알고 싶다면 심화 가이드 <a href="/insights/ziwei-doushu-stars-intro/">자미두수 주성 해설</a>을 참고하세요.</p>`,
